// ─── DIFFICULTIES (derived from puzzle bank — app adapts to any config) ──
const DIFFICULTIES = {};
for (const [key, data] of Object.entries(PUZZLE_BANK)) {
  const labels = { easy: "Easy", medium: "Medium", hard: "Hard", extreme: "Extreme" };
  DIFFICULTIES[key] = { label: labels[key] || key, rows: data.r, cols: data.c, pairs: data.p };
}

// ─── SEEDED PRNG ─────────────────────────────────────────────────────
function createRNG(seed) {
  let s = seed | 0;
  return () => { s = (s * 1664525 + 1013904223) | 0; return (s >>> 0) / 4294967296; };
}

function getDailySeed() {
  const d = new Date();
  return d.getFullYear() * 10000 + (d.getMonth() + 1) * 100 + d.getDate();
}

// ─── PUZZLE LOADER (converts bank format to app format) ─────────────
function tracePath(solutionGrid, rows, cols, pairId, startR, startC) {
  // BFS/DFS trace from start through connected cells of same pairId
  const visited = new Set();
  const path = [];
  const stack = [{ r: startR, c: startC }];
  // Build adjacency-ordered path from start
  let r = startR, c = startC;
  visited.add(`${r},${c}`);
  path.push({ r, c });
  
  let changed = true;
  while (changed) {
    changed = false;
    const dirs = [[0,1],[0,-1],[1,0],[-1,0]];
    for (const [dr, dc] of dirs) {
      const nr = r + dr, nc = c + dc;
      if (nr < 0 || nr >= rows || nc < 0 || nc >= cols) continue;
      if (visited.has(`${nr},${nc}`)) continue;
      if (solutionGrid[nr][nc] !== pairId) continue;
      visited.add(`${nr},${nc}`);
      path.push({ r: nr, c: nc });
      r = nr; c = nc;
      changed = true;
      break;
    }
  }
  return path;
}

function loadPuzzle(difficulty, index) {
  const bank = PUZZLE_BANK[difficulty];
  if (!bank || !bank.z || !bank.z.length) return null;
  const idx = index % bank.z.length;
  const p = bank.z[idx];
  const rows = bank.r, cols = bank.c, pairs = bank.p;
  
  const endpoints = p.e.map((ep, i) => ({
    id: i, start: { r: ep[0], c: ep[1] }, end: { r: ep[2], c: ep[3] },
  }));
  
  const solutionGrid = p.s;
  
  // Reconstruct ordered path segments from solution grid
  const segments = endpoints.map(ep =>
    tracePath(solutionGrid, rows, cols, ep.id, ep.start.r, ep.start.c)
  );
  
  return { rows, cols, pairs, endpoints, solutionGrid, segments };
}

// ─── GAME LOGIC (pure functions, no UI) ──────────────────────────────────
function isAdjacent(a, b) {
  return Math.abs(a.r - b.r) + Math.abs(a.c - b.c) === 1;
}

function cellKey(r, c) { return `${r},${c}`; }

// Interpolate skipped cells for fast swipes (straight lines only)
function interpolateCells(from, to) {
  const cells = [];
  if (from.r === to.r && from.c !== to.c) {
    const step = to.c > from.c ? 1 : -1;
    for (let c = from.c + step; step > 0 ? c <= to.c : c >= to.c; c += step) {
      cells.push({ r: from.r, c });
    }
  } else if (from.c === to.c && from.r !== to.r) {
    const step = to.r > from.r ? 1 : -1;
    for (let r = from.r + step; step > 0 ? r <= to.r : r >= to.r; r += step) {
      cells.push({ r, c: from.c });
    }
  }
  return cells; // empty for diagonal/L-shaped jumps (too ambiguous)
}

function checkWin(playerPaths, puzzle) {
  if (playerPaths.size !== puzzle.pairs) return false;
  const occupied = new Set();
  for (const [pairId, cells] of playerPaths) {
    const ep = puzzle.endpoints[pairId];
    if (cells.length < 2) return false;
    const first = cells[0], last = cells[cells.length - 1];
    const startsOk = (first.r === ep.start.r && first.c === ep.start.c) ||
                     (first.r === ep.end.r && first.c === ep.end.c);
    const endsOk = (last.r === ep.start.r && last.c === ep.start.c) ||
                   (last.r === ep.end.r && last.c === ep.end.c);
    if (!startsOk || !endsOk) return false;
    if (first.r === last.r && first.c === last.c) return false;
    for (const cell of cells) {
      const k = cellKey(cell.r, cell.c);
      if (occupied.has(k)) return false;
      occupied.add(k);
    }
  }
  // ALL cells must be filled — core Arukone rule
  return occupied.size === puzzle.rows * puzzle.cols;
}

